CREATE TABLE `enterprise_plan` (
	`enterprise_plan_id` integer PRIMARY KEY NOT NULL,
	`account_id` integer NOT NULL,
	`calls_per_period` integer NOT NULL,
	`calls_per_minute` integer NOT NULL,
	`period_start` text NOT NULL,
	`period_end` text NOT NULL,
	`ended_at` text,
	FOREIGN KEY (`account_id`) REFERENCES `developer_account`(`account_id`) ON UPDATE no action ON DELETE no action,
	CONSTRAINT "enterprise_plan_calls_per_period" CHECK(calls_per_period > 0),
	CONSTRAINT "enterprise_plan_calls_per_minute" CHECK(calls_per_minute > 0),
	CONSTRAINT "enterprise_plan_period" CHECK(period_start < period_end)
) STRICT;
