	CONSTRAINT "subscription_plan" CHECK(plan IN ('starter', 'pro')),
	CONSTRAINT "subscription_status" CHECK(status IN ('incomplete', 'incomplete_expired', 'trialing', 'active', 'past_due', 'canceled', 'unpaid', 'paused')),
	CONSTRAINT "subscription_reference_id" CHECK(reference_id GLOB '[1-9]*' AND reference_id NOT GLOB '*[^0-9]*'),
	CONSTRAINT "subscription_period" CHECK(period_start IS NULL OR period_end IS NULL OR period_start < period_end),
	CONSTRAINT "subscription_serving_period" CHECK(status NOT IN ('active', 'trialing', 'past_due') OR (period_start IS NOT NULL AND period_end IS NOT NULL)),
